/*
 * A018497  Divisors of 518.
 * https://oeis.org/A018497
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full, easy
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 8, u32 n <= 8, u64 n <= 8, u128 n <= 8,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Divisors of 518 sorted ascending */

#include <stddef.h>

seq_t a(idx_t n)
{
    /* 518 = 2 * 7 * 37, so the 8 divisors are generated by all
       combinations of these primes (exponent 0 or 1 for each). */

    if (n < 1 || n > 8)
        return (seq_t)0;

    seq_t divs[8];
    size_t idx = 0;

    for (int i = 0; i <= 1; ++i) {
        seq_t v1 = i ? (seq_t)2 : (seq_t)1;
        for (int j = 0; j <= 1; ++j) {
            seq_t v2 = v1 * (j ? (seq_t)7 : (seq_t)1);
            for (int k = 0; k <= 1; ++k) {
                divs[idx++] = v2 * (k ? (seq_t)37 : (seq_t)1);
            }
        }
    }

    /* Simple insertion sort for the 8 elements */
    for (size_t i = 1; i < 8; ++i) {
        seq_t key = divs[i];
        size_t j = i;
        while (j > 0 && divs[j - 1] > key) {
            divs[j] = divs[j - 1];
            --j;
        }
        divs[j] = key;
    }

    return divs[n - 1];
}
